.sidenav {
  height: 100%;
  width: 100%;
  position: fixed;
  z-index: 1;
  top: 0;
  left: 0;
  background-color: #16a34a;
  overflow-x: hidden;
  padding-top: 20px;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

.sidenav a {
  padding: 10px 15px;
  text-decoration: none;
  font-size: 16px;
  color: #ffffff;
  display: block;
  cursor: pointer;
}

.sidenav a:hover {
  color: #f1f1f1;
  background-color: rgba(255, 255, 255, 0.1);
}

.sidenav .subnav {
  display: none;
  padding-left: 15px;
