// Defining the SideBar component as a functional component
function SideBar() {
  // State to manage active accordion items
  const [activeAccordions, setActiveAccordions] = useState({});

  // Function to toggle accordion
  const toggleAccordion = (index) => {
    setActiveAccordions((prevState) => ({
      ...prevState,
      [index]: !prevState[index],
    }));
  };

  // Accessing navigation items from Appsmith model
  let navItems = appsmith.model.navItems;

  // Determining the initially selected tab ID based on the current page
  let initialTabId = navItems.find(item => item.title === appsmith.model.page)?.title;
  const [selectedItem, setSelectedItem] = useState(initialTabId);

  return (
    // Rendering the SideBar component
    <div className="sidenav">
      {navItems.map((item) => {
        if (!item.subItems) {
          return (
            // Rendering navigation items without sub-items
            <a onClick={() => appsmith.triggerEvent("navigateToTab", { tabName: item.title })}>
              <span className="icon">{item.icon}</span>
              {item.title}
            </a>
          );
        } else {
          return (
            // Rendering navigation items with sub-items
            <>
              <a onClick={() => toggleAccordion(item.title)} className={activeAccordions[item.title] ? 'accordion active' : 'accordion'}>
                <span className="icon">{item.icon}</span>
                {item.title}
              </a>
              <div className="subnav" style={{ display: activeAccordions[item.title] ? 'block' : 'none' }}>
                {/* Rendering sub-items */}
                {item.subItems.map((subItem) => (
                  <a onClick={() => appsmith.triggerEvent("navigateToTab", { tabName: subItem.title })}>
                    <span className="icon">{subItem.icon}</span>
                    {subItem.title}
                  </a>
                ))}
              </div>
            </>
          );
        }
      })}
    </div>
  );
}

// Rendering the SideBar component when the page is ready
appsmith.onReady(() => {
